// Synthetic QA only. Files and identities are generated by this test.
// No user data, decrypted screenshots or private uploads leave the local lab.
import { chromium, webkit, expect } from '@playwright/test'
import assert from 'node:assert/strict'
import { origin, button, label, accountFixture, cleanupFixtures, monitorRuntime } from './account-qa.mjs'

const png = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEklEQVR4nGP4z/D/PwgzQOn/AGeqC/W88sLDAAAAAElFTkSuQmCC', 'base64')
const fileSelector = '.chatify-message-composer input[type=file]'
async function ready(page) {
  await page.goto(`${origin}/messages`)
  await expect(page.locator('.messages-screen')).toHaveAttribute('data-crypto-stage', 'ready', { timeout: 90000 })
}
for (const engine of (process.env.APP_BROWSERS ?? 'chromium,webkit').split(',')) {
  const browser = await ({ chromium, webkit }[engine]).launch({ headless: true })
  const fixtures = [], errors = [], diagnostics = { nativePhotoPoll: 0 }, uploads = []
  let stage = 'account', sender
  try {
    const a = await accountFixture(browser, `${engine} attachment sender`, fixtures)
    sender = a
    const b = await accountFixture(browser, `${engine} attachment receiver`, fixtures)
    for (const item of fixtures) await monitorRuntime(item.page, engine, errors, diagnostics)
    a.page.on('response', response => {
      if (new URL(response.url()).pathname.includes('/_matrix/media/v3/upload'))
        uploads.push({ status: response.status(), type: response.request().headers()['content-type'] })
    })
    await ready(a.page)
    await button(a.page, 'Новый чат').click()
    await label(a.page, 'ID или @username').fill(b.me.account.publicId)
    await button(a.page, 'Написать').click()
    await expect(a.page.locator('.message-composer')).toBeVisible({ timeout: 30000 })
    stage = 'image-send'
    await a.page.locator(fileSelector).setInputFiles({ name: 'synthetic.png', mimeType: 'image/png', buffer: png })
    await expect(a.page.locator('.chatify-composer-attachment')).toContainText('synthetic.png')
    await expect(a.page.locator('.chatify-attachment-privacy')).toBeVisible()
    await button(a.page, 'Отправить').click()
    await expect(a.page.locator('.message-bubble .chatify-attachment-open')).toHaveCount(1, { timeout: 45000 })
    await expect(a.page.locator('.chatify-composer-attachment')).toHaveCount(0)
    stage = 'image-receive'
    await ready(b.page)
    await expect(b.page.locator('.chat-row')).toHaveCount(1, { timeout: 35000 })
    await b.page.locator('.chat-row').click()
    await expect(b.page.locator('.chatify-attachment-open')).toHaveCount(1, { timeout: 45000 })
    await b.page.locator('.chatify-attachment-open').click()
    await expect(b.page.locator('.chatify-attachment-image')).toBeVisible({ timeout: 25000 })
    // A receiver must not see plaintext except after clicking decrypt.
    stage = 'document-send-receive'
    await a.page.locator(fileSelector).setInputFiles({
      name: 'synthetic.pdf', mimeType: 'application/pdf', buffer: Buffer.from('%PDF-1.4\nSynthetic QA file\n%%EOF'),
    })
    await a.page.locator('.chatify-composer-attachment').getByRole('button', { name: 'Убрать вложение' }).click()
    await expect(a.page.locator('.chatify-composer-attachment')).toHaveCount(0)
    await a.page.locator(fileSelector).setInputFiles({
      name: 'synthetic.pdf', mimeType: 'application/pdf', buffer: Buffer.from('%PDF-1.4\nSynthetic QA file\n%%EOF'),
    })
    await button(a.page, 'Отправить').click()
    await expect(b.page.locator('.chatify-attachment-file')).toBeVisible({ timeout: 45000 })
    const downloadPromise = b.page.waitForEvent('download')
    await b.page.locator('.chatify-attachment-file').click()
    const download = await downloadPromise
    assert.equal(download.suggestedFilename(), 'synthetic.pdf')
    stage = 'failed-upload-and-retry'
    const uploadPath = '**/_matrix/media/v3/upload**'
    await a.page.route(uploadPath, route => route.fulfill({
      status: 503, contentType: 'application/json', body: '{"errcode":"M_UNKNOWN","error":"QA unavailable"}',
    }))
    await a.page.locator(fileSelector).setInputFiles({ name: 'retry.png', mimeType: 'image/png', buffer: png })
    await button(a.page, 'Отправить').click()
    await expect(a.page.getByRole('alert')).toContainText('Не удалось отправить вложение', { timeout: 30000 })
    await expect(a.page.locator('.chatify-composer-attachment')).toContainText('retry.png')
    await a.page.unroute(uploadPath)
    await button(a.page, 'Отправить').click()
    await expect(b.page.locator('.chatify-attachment')).toHaveCount(3, { timeout: 45000 })
    assert.equal(uploads.filter(entry => entry.status === 200).length, 3)
    assert(uploads.every(entry => entry.type === 'application/octet-stream'))
    assert.deepEqual(errors, [])
    console.log(`${engine}: encrypted photo/file, explicit decrypt/download, composer cancel, failed upload retry, ciphertext upload passed`)
  } catch (error) {
    console.error(`${engine}: attachment QA failed at ${stage}`, error instanceof Error ? error.name : 'unknown')
    const state = await sender?.page?.evaluate(async () => {
      const store = await import('/src/messages/store.ts')
      return { connection: store.connection.value, crypto: store.diagnostic.value,
        selected: !!store.selected.value,
        timeline: store.messages.value.map(row => ({
          status: row.status, locked: row.locked,
          attachment: !!row.attachment, voice: !!row.voice, hasText: !!row.body,
        })) }
    }).catch(() => ({ unavailable: true }))
    console.error({ errors: errors.length, uploads, diagnostics, state })
    throw error
  } finally {
    await cleanupFixtures(fixtures)
    await browser.close()
  }
}
